<?php require_once __DIR__.'/../app/bootstrap.php'; if(isLoggedIn()){header('Location: feed.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $username=trim($_POST['username']??'');$full=trim($_POST['full_name']??'');$pass=$_POST['password']??''; if($pass!==($_POST['confirm_password']??''))$error='Mật khẩu xác nhận không khớp.';else{$r=api('POST',apiPath('register'),['username'=>$username,'full_name'=>$full,'password'=>$pass]);if($r['ok']){flash('success','Đăng ký thành công. Vui lòng đăng nhập.');header('Location: login.php');exit;}else$error=apiMessage($r,'Không thể tạo tài khoản.');}} ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Đăng ký · UniConnect</title><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Manrope:wght@600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/style.css"></head><body class="auth-body"><div class="auth-wrap"><section class="auth-visual"><a class="brand brand-light" href="login.php"><span class="brand-mark">u</span><span>Uni<span>Connect</span></span></a><div class="visual-copy"><span class="eyebrow">WELCOME TO UNICONNECT</span><h1>Mỗi kết nối<br><em>bắt đầu từ đây.</em></h1><p>Tạo tài khoản để chia sẻ bài viết và khám phá những kết nối mới.</p></div><div class="visual-orbit orbit-one"></div><div class="visual-orbit orbit-two"></div><div class="visual-note"><span class="note-dot"></span> Cộng đồng của bạn đang chờ</div></section><section class="auth-panel"><div class="auth-card"><div class="auth-kicker">THAM GIA CỘNG ĐỒNG</div><h2>Tạo tài khoản</h2><p class="muted">Chỉ mất một phút để bắt đầu.</p><?php if($error): ?><div class="alert alert-error"><?=e($error)?></div><?php endif; ?><form method="post" class="form-stack"><label>Họ và tên<input name="full_name" required placeholder="Nguyễn Văn A"></label><label>Tên đăng nhập<input name="username" required placeholder="Tên đăng nhập"></label><label>Mật khẩu<input type="password" name="password" minlength="8" required placeholder="Ít nhất 8 ký tự"></label><label>Xác nhận mật khẩu<input type="password" name="confirm_password" required placeholder="Nhập lại mật khẩu"></label><button class="btn btn-primary btn-full">Tạo tài khoản <span>→</span></button></form><p class="auth-switch">Đã có tài khoản? <a href="login.php">Đăng nhập</a></p></div></section></div></body></html>
